
#include "../attentionMultiHeadKVCache-cuda/flashinfer_ops.cuh"
#include <chrono>
#include <vector>
#include <cmath>
#include <string>
#include <cstdio>
using namespace flashinfer;
#define CK(c) do{auto e=(c);if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(2);}}while(0)
struct Base{virtual void launch()=0;virtual void append(std::vector<float>&out,bool&ok,double&ma,double&mr)=0;virtual ~Base(){};};
template<class T>struct Case:Base{int n;T*q,*k,*v,*o;std::vector<T>hq,hk,hv;std::vector<double>gold;
Case(int n_,int kind,std::vector<float>&prefix):n(n_),hq(2048),hk(n*256),hv(n*256),gold(2048){for(int i=0;i<2048;i++)hq[i]=T(float((7*i+3)%31-15)/16.f);for(int i=0;i<n*256;i++){hk[i]=T(float((11*i+5)%29-14)/16.f);hv[i]=T(float((13*i+7)%27-13)/16.f);}prefix.insert(prefix.end(),{float(kind),float(n),32.f,4.f,64.f});for(auto x:hq)prefix.push_back(float(x));for(auto x:hk)prefix.push_back(float(x));for(auto x:hv)prefix.push_back(float(x));
for(int h=0;h<32;h++){int kh=h/8;std::vector<double>w(n);double mx=-1e300,sum=0;for(int s=0;s<n;s++){double z=0;for(int c=0;c<64;c++)z+=double(float(hq[h*64+c]))*double(float(hk[s*256+kh*64+c]));w[s]=z/8;mx=std::max(mx,w[s]);}for(auto&z:w){z=exp(z-mx);sum+=z;}for(int c=0;c<64;c++){double val=0;for(int s=0;s<n;s++)val+=w[s]/sum*double(float(hv[s*256+kh*64+c]));gold[h*64+c]=val;}}
CK(cudaMalloc(&q,2048*sizeof(T)));CK(cudaMalloc(&k,n*256*sizeof(T)));CK(cudaMalloc(&v,n*256*sizeof(T)));CK(cudaMalloc(&o,2048*sizeof(T)));CK(cudaMemcpy(q,hq.data(),2048*sizeof(T),cudaMemcpyHostToDevice));CK(cudaMemcpy(k,hk.data(),n*256*sizeof(T),cudaMemcpyHostToDevice));CK(cudaMemcpy(v,hv.data(),n*256*sizeof(T),cudaMemcpyHostToDevice));}
void launch(){using Params=SingleDecodeParams<T,T,T>;using Variant=DefaultAttention<false,false,false,false>;Params p(q,k,v,o,nullptr,n,32,4,QKVLayout::kNHD,64,-1,0.f,.125f,1.f,1e4f);p.kv_chunk_size=n;auto kernel=SingleDecodeWithKVCacheKernel<PosEncodingMode::kNone,1,1,8,8,8,8,Variant,Params>;CK(cudaFuncSetAttribute(kernel,cudaFuncAttributeMaxDynamicSharedMemorySize,16896));void*args[]={(void*)&p};CK(cudaLaunchKernel((void*)kernel,dim3(1,4),dim3(8,8,8),args,16896,nullptr));}
void append(std::vector<float>&out,bool&ok,double&ma,double&mr){std::vector<T>got(2048);CK(cudaMemcpy(got.data(),o,2048*sizeof(T),cudaMemcpyDeviceToHost));for(int i=0;i<2048;i++){double x=float(got[i]),err=abs(x-gold[i]);ma=std::max(ma,err);mr=std::max(mr,err/std::max(abs(gold[i]),.002));ok&=std::isfinite(x)&&err<=.002+.01*abs(gold[i]);out.push_back(float(got[i]));}}
~Case(){cudaFree(q);cudaFree(k);cudaFree(v);cudaFree(o);}};
int main(){std::vector<float>prefix;std::vector<Base*>cases;for(int kind:{1,2})for(int n:{1,3,65,127}){if(kind==1)cases.push_back(new Case<half>(n,kind,prefix));else cases.push_back(new Case<nv_bfloat16>(n,kind,prefix));}for(auto c:cases){c->launch();c->launch();}CK(cudaDeviceSynchronize());for(int trial=1;trial<=5;trial++){std::vector<double>times;for(auto c:cases){auto start=std::chrono::steady_clock::now();for(int r=0;r<20;r++)c->launch();CK(cudaDeviceSynchronize());times.push_back(std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/20);}auto out=prefix;bool ok=true;double ma=0,mr=0,total=0;for(auto c:cases)c->append(out,ok,ma,mr);std::string timesjson;for(auto t:times){total+=t;if(!timesjson.empty())timesjson+=",";char buf[64];snprintf(buf,sizeof(buf),"%.12g",t);timesjson+=buf;}std::string path=std::string(getenv("STUDY_OUTPUT_DIR")?getenv("STUDY_OUTPUT_DIR"):".")+"/output_trial"+std::to_string(trial)+".bin";FILE*f=fopen(path.c_str(),"wb");if(!f)return 4;fwrite(out.data(),4,out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"component_seconds\":[%s],\"correct\":%s,\"checked_values\":16384,\"max_abs_error\":%.12g,\"max_rel_error\":%.12g,\"relative_error_denominator_floor\":0.002,\"timing_region\":\"eight_decode_case_kernel_loop_means\",\"jit_excluded\":true,\"internal_repeats\":20,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,total,timesjson.c_str(),ok?"true":"false",ma,mr,path.c_str(),out.size());if(!ok)return 5;}for(auto c:cases)delete c;puts("PASS");}
